dao.select:
SELECT * FROM ( SELECT observador.OBSERVADORES usuarioObservadores ,SATCO_TAREA.TAR_ID tareaId ,SATCO_TAREA.CAS_ID casoId ,SATCO_TAREA.TAR_NOMBRE nombreTarea ,SATCO_TAREA.TAR_DESCRIPCION descripcion ,SATCO_TAREA.TAR_ESTADO estado ,SATCO_SUB_TIPO_ATENCION.STA_NOMBRE nombreSubProducto ,SATCO_SUB_TIPO_ATENCION.STA_ID idSubProducto ,SATCO_TIPO_TAREA.TT_ID tipoTareaId ,SATCO_TIPO_TAREA.TT_NOMBRE nombreTipoTarea ,SATCO_TIPO_TAREA.TT_IMPLEMENTACION implementacionTipoTarea ,SATCO_TAREA.TAR_FECHA_CREACION fechaCreacion ,SATCO_TAREA.TAR_FECHA_POS_SOL fechaPosSolucion ,SATCO_TAREA.TAR_FECHA_SOLUCION fechaSolucion ,SATCO_TAREA.TAR_PRIORIDAD prioridad ,SATCO_TAREA.TAR_USERS_SUGERIDO usuariosSugerido ,SATCO_TAREA.TAR_ID_PADRE idTareaPadre ,SATCO_TAREA.TAR_DATA dataTarea ,SATCO_CANAL_INGRESO.CANVAR_NOMBRE canal ,SATCO_CLIENTE.CLI_NUM_IDENTIFICACION identificacionCliente ,SATCO_CLIENTE.CLI_DV_IDENTIFICACION dvIdentificacionCliente ,SATCO_CLIENTE.CLI_NOMBRE nombreCliente ,SATCO_PACIENTE.PAC_APELLIDOS apellidosCliente ,ClienteEmpresa.CLI_NUM_IDENTIFICACION identificacionEmpresa ,ClienteEmpresa.CLI_DV_IDENTIFICACION dvIdentificacionEmpresa ,ClienteEmpresa.CLI_NOMBRE nombreEmpresa ,SATCO_USUARIO_TAREA.USUARIO_LDAP usuarioAsignado ,SATCO_EMPRESA.EMP_RAZON_SOCIAL razonSocialEmpresa ,SATCO_CLIENTE.CLI_EMAIL emailCliente ,ClienteEmpresa.CLI_EMAIL emailEmpresa ,SATCO_CASO.CAS_FECHA_CREACION fechaCreacionCaso ,SATCO_AREA.AREA_NOMBRE nombreArea ,SATCO_AREA.AREA_ID idArea ,SATCO_TIPO_ATENCION.TAT_NOMBRE nombreProducto ,SATCO_TIPO_ATENCION.TAT_ID idProducto ,ClienteEmpresa.CLI_PPN_EXT ppnEmpresa ,SATCO_CLIENTE.CLI_PPN_EXT ppnCliente ,SATCO_CASO.PAC_ID idCliente ,SATCO_CASO.EMP_ID idEmpresa ,SATCO_TAREA.CANNU_ID idCanal ,SATCO_TIPO_TAREA_CONFIG.TTC_DIAS_ALERTA diasAlerta ,SATCO_CASO.CAS_ID_PADRE idCasoPadre ,NVL(adjunto.CANTIDAD,0) cantidadAdjuntos ,NVL(adjuntoTipo.CANTIDAD,0) cantidadAdjuntosTipo ,ROWNUM num FROM SATCO_TAREA LEFT JOIN SATCO_USUARIO_TAREA ON (SATCO_TAREA.TAR_ID = SATCO_USUARIO_TAREA.TAR_ID) JOIN SATCO_CASO ON (SATCO_TAREA.CAS_ID = SATCO_CASO.CAS_ID) LEFT JOIN SATCO_SUB_TIPO_ATENCION ON (SATCO_SUB_TIPO_ATENCION.STA_ID = SATCO_TAREA.STA_ID) LEFT JOIN SATCO_TIPO_TAREA ON (SATCO_TIPO_TAREA.TT_ID = SATCO_TAREA.TT_ID) JOIN SATCO_CANAL_INGRESO ON (SATCO_CANAL_INGRESO.CANNU_ID = SATCO_TAREA.CANNU_ID) LEFT JOIN SATCO_CLIENTE ON (SATCO_CLIENTE.CLI_ID = SATCO_CASO.PAC_ID) LEFT JOIN SATCO_EMPRESA ON (SATCO_EMPRESA.EMP_ID = SATCO_CASO.EMP_ID) LEFT JOIN SATCO_PACIENTE ON (SATCO_PACIENTE.PAC_ID = SATCO_CLIENTE.CLI_ID) LEFT JOIN SATCO_CLIENTE ClienteEmpresa ON (ClienteEmpresa.CLI_ID = SATCO_EMPRESA.EMP_ID) LEFT JOIN SATCO_AREA ON (SATCO_AREA.AREA_ID = SATCO_TAREA.AREA_ID) LEFT JOIN SATCO_TIPO_ATENCION ON (SATCO_TIPO_ATENCION.TAT_ACTIVO = #{tipoAtencionEsActivo} AND SATCO_TIPO_ATENCION.TAT_ID = SATCO_TAREA.TAT_ID) LEFT JOIN SATCO_TIPO_TAREA_CONFIG ON (SATCO_TIPO_TAREA_CONFIG.STA_ID = SATCO_TAREA.STA_ID AND SATCO_TIPO_TAREA_CONFIG.TT_ID = SATCO_TAREA.TT_ID)
LEFT JOIN SATCO_OBSERVADOR_TAREA ON (SATCO_OBSERVADOR_TAREA.USUARIO_LDAP = #{usuarioLDAP} AND SATCO_OBSERVADOR_TAREA.TAR_ID = SATCO_TAREA.TAR_ID)
LEFT JOIN ( SELECT COUNT(SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_TAREA) CANTIDAD ,SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_TAREA ID_TAREA FROM SATCO_ARCHIVO_ADJUNTO_TAREA JOIN SATCO_TAREA sa ON (sa.TAR_ID = SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_TAREA) WHERE
AND sa.AREA_ID = #{idArea}
AND sa.TAR_PRIORIDAD = #{tareaEsPrioridad}
AND sa.CAS_ID = #{idCaso}
AND sa.TAR_FECHA_CREACION <= #{fechaCreacionTo}
AND sa.TAR_FECHA_CREACION >= #{fechaCreacionFrom}
AND sa.TAR_ESTADO = #{tareaEstado}
GROUP BY SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_TAREA ) adjunto ON (adjunto.ID_TAREA = SATCO_TAREA.TAR_ID) LEFT JOIN ( SELECT COUNT(SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_TAREA) CANTIDAD ,SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_TAREA ID_TAREA,sa.TT_ID TT_ID FROM SATCO_ARCHIVO_ADJUNTO_TAREA JOIN SATCO_TAREA sa ON (sa.TAR_ID = SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_TAREA) JOIN SATCO_TTAREA_TADJUNTO ON (SATCO_TTAREA_TADJUNTO.TT_ID = sa.TT_ID) JOIN SATCO_ARCHIVO_ADJUNTO ON ((SATCO_ARCHIVO_ADJUNTO.ACD_TIPO = SATCO_TTAREA_TADJUNTO.TACA_ID AND SATCO_ARCHIVO_ADJUNTO.ACD_ID = SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_ARCHIVO_ADJUNTO)) WHERE
AND sa.AREA_ID = #{idArea}
AND sa.TAR_PRIORIDAD = #{tareaEsPrioridad}
AND sa.CAS_ID = #{idCaso}
AND sa.TAR_FECHA_CREACION <= #{fechaCreacionTo}
AND sa.TAR_FECHA_CREACION >= #{fechaCreacionFrom}
AND sa.TAR_ESTADO = #{tareaEstado}
GROUP BY SATCO_ARCHIVO_ADJUNTO_TAREA.ACDT_ID_TAREA, sa.TT_ID ) adjuntoTipo ON ((adjuntoTipo.ID_TAREA = SATCO_TAREA.TAR_ID AND adjuntoTipo.TT_ID = SATCO_TAREA.TT_ID))
LEFT JOIN ( SELECT SATCO_OBSERVADOR_TAREA.TAR_ID ,LISTAGG(SATCO_OBSERVADOR_TAREA.USUARIO_LDAP,',') WITHIN GROUP (ORDER BY SATCO_OBSERVADOR_TAREA.TAR_ID) OBSERVADORES FROM SATCO_OBSERVADOR_TAREA GROUP BY SATCO_OBSERVADOR_TAREA.TAR_ID ) observador ON (observador.TAR_ID = SATCO_TAREA.TAR_ID) WHERE SATCO_TAREA.TAR_ESTADO = #{tareaEstado}
AND (SATCO_USUARIO_TAREA.USUARIO_LDAP IS NULL)
AND (SATCO_USUARIO_TAREA.USUARIO_LDAP = #{usuarioLDAP} OR SATCO_OBSERVADOR_TAREA.USUARIO_LDAP = #{usuarioLDAP})
AND SATCO_TAREA.TAR_FECHA_CREACION >= #{fechaCreacionFrom}
AND SATCO_TAREA.TAR_FECHA_CREACION <= #{fechaCreacionTo}
AND (SATCO_CASO.CAS_ID_PADRE = #{idCasoPadre} OR SATCO_TAREA.CAS_ID = #{idCaso})
AND SATCO_TAREA.TAR_PRIORIDAD = #{tareaEsPrioridad}
AND SATCO_TAREA.AREA_ID = #{idArea}
AND UPPER(SATCO_CLIENTE.CLI_NUM_IDENTIFICACION) = #{identificacionNumero} AND UPPER(SATCO_CLIENTE.CLI_DV_IDENTIFICACION) = #{identificacionDV}
AND SATCO_TIPO_ATENCION.TAT_ID = #{idTipoDeAtencion}
) where num BETWEEN #{pagFinalRow} AND #{pagInitialRow}
